func newTransactionsGetCmd(c *client.Client, opts *output.Options) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "get <transaction_id>",
		Short: "Get a transaction",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			path := "/transactions/{transaction_id}"
			path = strings.Replace(path, "{"+"transaction_id"+"}", args[0], 1)

			qp := make(map[string]string)
			if v, _ := cmd.Flags().GetString("include"); v != "" {
				qp["include"] = v
			}

			var bodyBytes []byte

			resp, err := c.Do("GET", path, qp, bodyBytes)
			if err != nil {
				return err
			}

			if resp.StatusCode >= 400 {
				return client.ParseAPIError(resp)
			}

			hasMore, cursor := output.ParsePagination(resp.Body)
			if hasMore {
				opts.NextCommand = output.SynthesizeNextCommand(cmd, cursor)
			} else {
				opts.NextCommand = ""
			}
			columns := transactionsGetColumns()
			return output.Print(resp.Body, columns, *opts)
		},
	}

	cmd.Flags().String("include", "", "Include related entities in the response. Use a comma-separated list to specify multiple entities.")

	return cmd
}

func transactionsGetColumns() []output.ColumnDef {
	return nil
}

