func newTransactionsPreviewCreateCmd(c *client.Client, opts *output.Options) *cobra.Command {
	cmd := &cobra.Command{
		Use:     "preview-create",
		Short:   "Preview a transaction",
		Long:    "Preview a transaction" + "\n\nBody schema:\n" + schema.RenderTree(transactionsPreviewCreateBodySchema, style.Profile{}) + "\nPass these fields as JSON with --json. Run with --schema for the full JSON Schema.",
		Example: "  paddle transactions preview-create --json '{\"items\":[{\"quantity\":1,\"price_id\":\"...\"}]}'\n  paddle transactions preview-create --json @transaction.json\n  some-command | paddle transactions preview-create --json -",
		Args:    cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			if ok, _ := cmd.Flags().GetBool("schema"); ok {
				return schema.PrintRaw(opts.Writer, transactionsPreviewCreateBodySchema, opts.Compact)
			}
			path := "/transactions/preview"

			qp := make(map[string]string)

			body := make(map[string]interface{})

			jsonInput, _ := cmd.Flags().GetString("json")
			if jsonInput != "" {
				raw, err := readJSONInput(jsonInput)
				if err != nil {
					return err
				}
				if err := json.Unmarshal(raw, &body); err != nil {
					return fmt.Errorf("invalid JSON input: %w", err)
				}
			}

			var bodyBytes []byte
			if len(body) > 0 {
				var err error
				bodyBytes, err = json.Marshal(body)
				if err != nil {
					return fmt.Errorf("encoding request body: %w", err)
				}
			}

			resp, err := c.Do("POST", path, qp, bodyBytes)
			if err != nil {
				return err
			}

			if resp.StatusCode >= 400 {
				return client.ParseAPIError(resp)
			}

			hasMore, cursor := output.ParsePagination(resp.Body)
			if hasMore {
				opts.NextCommand = output.SynthesizeNextCommand(cmd, cursor)
			} else {
				opts.NextCommand = ""
			}
			columns := transactionsPreviewCreateColumns()
			return output.Print(resp.Body, columns, *opts)
		},
	}

	cmd.Flags().String("json", "", "Request body as JSON: inline ('{…}'), from a file (@body.json), or from stdin (-)")
	cmd.Flags().Bool("schema", false, "Print the request body JSON schema and exit")

	return cmd
}

func transactionsPreviewCreateColumns() []output.ColumnDef {
	return nil
}

